// Standard pass-through vertex shader used for rendering full screen quads
static const char _vertexShaderCode[] = R"(#version 410 core
uniform vec2 MaxUV;
layout( location = 0 ) in vec4 vPosition;
layout( location = 1 ) in vec2 vUV;
out vec2 v_uv;       // normalized 0-1, used for fragCoord and ISF coordinate math
out vec2 v_texCoord; // MaxUV-scaled, used for sampling the input texture
void main()
{
	gl_Position = vPosition;
	v_uv = vUV;
	v_texCoord = vUV * MaxUV; // scales to actual valid texture extent
}
)";

// Fragment shader wrapper that injects constants and Shadertoy equivalents
static const char* _fragmentShaderCode = R"(#version 410 core
/* FFM_SHADER_UNIFORMS */

in vec2 v_uv;       // normalized 0-1 for coordinate calculations
in vec2 v_texCoord; // MaxUV-scaled for input texture sampling
out vec4 fragColor;
uniform sampler2D inputTexture;
uniform vec2 MaxUV; // valid texture extent; use for all inputTexture sampling coordinates

/* FFM_SHADER_BODY */

void main() {
    vec2 fragCoord = v_uv * iResolution.xy;
    vec4 finalColor = vec4(0.0);
    
    // FFMaker Wrapper to execute the shader code.
    /* FFM_SHADER_MAIN_CALL */
    
    fragColor = finalColor;
}
)";

